@Override
    public boolean add(final E element) {
        Objects.requireNonNull(element, "element");

        if (isAtFullCapacity()) {
            remove();
        }

        elements[end++] = element;

        if (end >= maxElements) {
            end = 0;
        }

        if (end == start) {
            full = true;
        }

        return true;






    }
